<!DOCTYPE html>
<html>
  <head>
    <title>Inspection Form for Operating Septic Systems</title>
    <style>
      body { margin: 0; padding: 0; font-family: Arial, sans-serif; font-size: 13px; }
      .page { width: 92%; padding: 20px; box-sizing: border-box; max-width: 700px; margin: auto; }
      .page2 { width: 92%; padding: 20px; box-sizing: border-box; max-width: 755px; margin: auto; page-break-before: always; }
      table { border-collapse: collapse; width: 100%; }
      .title-row td { font-size: 16px; font-weight: bold; padding-bottom: 6px; text-align: center; }
      .divider td { padding: 8px 0 4px 0; }
      .divider-line { border-top: 1px solid #000; }
      .section-header td { font-size: 14px; font-weight: bold; text-align: center; padding: 4px 0; }
      .checkbox { display: inline-block; width: 11px; height: 11px; border: 1px solid #000; vertical-align: middle; }
      .row td { padding: 3px 0; }
      .indented td { padding: 2px 0 2px 40px; }
      .underline { text-decoration: underline; }
      .bold-underline { font-weight: bold; text-decoration: underline; }
      .italic-bold { font-style: italic; font-weight: bold; }
      .line-row td { padding: 2px 0; height: 20px; border-bottom: 1px solid #aaa; }
    </style>
  </head>
  <body>
    <div class="page">
      <table>

        <!-- Title -->
        <tr class="title-row">
          <td colspan="4">Inspection Form for Operating Septic Systems</td>
        </tr>

        <!-- Type of Inspection label -->
        <tr>
          <td colspan="4" align="center" style="padding-bottom:10px;">
            <b>Type of Inspection:&nbsp;</b>
            <span style="display:inline-block;width:11px;height:11px;border:1px solid #000;vertical-align:middle;"></span>&nbsp;Realtor
            &nbsp;&nbsp;
            <span style="display:inline-block;width:11px;height:11px;border:1px solid #000;vertical-align:middle;"></span>&nbsp;Routine Maintenance
          </td>
        </tr>

        <!-- Date / Time / Weather -->
        <tr class="row">
          <td style="width:33%;"><b>Date of Inspection:</b> </td>
          <td style="width:33%;"><b>Time:</b> </td>
          <td style="width:34%;" colspan="2"><b>Weather:</b> </td>
        </tr>

        <!-- Inspector -->
        <tr class="row">
          <td colspan="4"><b>Inspector Name &amp; Company:&nbsp;</b><span class="underline">Paul Balberde, Bob's Sweetwater Pumping Service</span></td>
        </tr>

        <!-- Site Address -->
        <tr class="row"><td colspan="4"><b>Site Address:</b> </td></tr>

        <!-- Tax Map -->
        <tr class="row"><td colspan="4"><b>Tax Map Number:</b> </td></tr>

        <!-- Type of System -->
        <tr class="row"><td colspan="4"><b>Type of System (DOH code if available):</b> </td></tr>

        <!-- Divider -->
        <tr class="divider"><td colspan="4"><div class="divider-line"></div></td></tr>

        <!-- SITE OBSERVATIONS Header -->
        <tr class="section-header"><td colspan="4">SITE OBSERVATIONS</td></tr>

        <!-- Property in use label -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Property in use:</b>
          </td>
        </tr>

        <!-- Options -->
        <tr>
          <td colspan="4" style="padding:2px 0;">
            <table style="width:100%; border-collapse:collapse;">
              <tr>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Yes
                </td>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;No
                </td>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Full time
                </td>
              </tr>

              <tr>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Vacation Rental
                </td>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Vacant
                </td>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Other
                </td>
              </tr>

              <tr>
                <td style="width:33.33%;">
                  <span class="checkbox"></span>&nbsp;Unknown
                </td>
                <td style="width:33.33%;"></td>
                <td style="width:33.33%;"></td>
              </tr>
            </table>
          </td>
        </tr>
        <tr>
          <td colspan="4" style="padding: 2px 0 6px 0;">
            <span class="checkbox"></span>&nbsp;Unknown
          </td>
        </tr>

        <!-- General Site Conditions label -->
        <tr><td colspan="4" style="padding-top:6px;"><b>General Site Conditions:</b></td></tr>

        <!-- Grass cover -->
        <tr>
          <td colspan="4" style="padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Grass cover/vegetation condition:&nbsp;<span class="underline">Cinder/rocks</span>
          </td>
        </tr>

        <!-- Surface Ponding row -->
        <tr>
          <td style="padding:2px 0; width:33%;"><span class="checkbox"></span>&nbsp;Surface Ponding</td>
          <td style="padding:2px 0; width:25%;"><span class="checkbox"></span>&nbsp;System area</td>
          <td style="padding:2px 0;" colspan="2"><span class="checkbox"></span>&nbsp;Other areas</td>
        </tr>

        <!-- Protective Barriers row -->
        <tr>
          <td style="padding:2px 0;"><span class="checkbox"></span>&nbsp;Protective Barriers Present</td>
          <td style="padding:2px 0;"><span class="checkbox"></span>&nbsp;Effective</td>
          <td style="padding:2px 0;" colspan="2"><span class="checkbox"></span>&nbsp;Not effective</td>
        </tr>

        <!-- Surface runoff label -->
        <tr>
          <td colspan="4" style="padding:2px 0;">
            <span class="checkbox"></span>&nbsp;<b>Surface runoff/gutters directed away from system</b>
          </td>
        </tr>
        <!-- Surface runoff options -->
        <tr>
          <td colspan="4" style="padding:2px 0 6px 0;">
            <span class="checkbox"></span>&nbsp;Yes&nbsp;&nbsp;&nbsp;&nbsp;
            <span class="checkbox"></span>&nbsp;No&nbsp;&nbsp;&nbsp;&nbsp;
            <span class="checkbox"></span>&nbsp;N/A
          </td>
        </tr>

        <!-- Malfunction label -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;"><b>Malfunction at time of inspection:</b></td>
        </tr>
        <!-- Malfunction options -->
        <tr>
          <td colspan="4" style="padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes&nbsp;&nbsp;&nbsp;&nbsp;
            <span class="checkbox"></span>&nbsp;No
          </td>
        </tr>

        <!-- Surface discharge items (indented) -->
        <tr class="indented">
          <td colspan="4">
            <span class="checkbox"></span>&nbsp;<b>Surface discharge via straight-pipe or damaged plumbing</b>
          </td>
        </tr>
        <tr>
          <td colspan="4" style="padding:2px 0 2px 60px;">
            <span class="checkbox"></span>&nbsp;Grey water&nbsp;&nbsp;&nbsp;&nbsp;
            <span class="checkbox"></span>&nbsp;Black water&nbsp;&nbsp;&nbsp;&nbsp;
            <span class="checkbox"></span>&nbsp;Unknown
          </td>
        </tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Surface discharge in area of tank</td></tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Surface discharge within tile field area</td></tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Surface discharge at edge of tile field area</td></tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Surface discharge - bleed-out away from system location</td></tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Evidence of past failure / Note evidence: </td></tr>
        <tr class="indented"><td colspan="4"><span class="checkbox"></span>&nbsp;Other problems noted below and on site diagram (diagram on page 2 of form)</td></tr>

        <!-- Divider -->
        <tr class="divider"><td colspan="4"><div class="divider-line"></div></td></tr>

        <!-- SYSTEM EVALUATION Header -->
        <tr class="section-header">
          <td colspan="4"><b>SYSTEM EVALUATION</b></td>
        </tr>

        <!-- Tank -->
        <tr>
          <td colspan="4" style="padding-top:8px;">
            <b><u>Tank</u></b>
          </td>
        </tr>

        <!-- Accessible -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Accessible:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <!-- Lid(s) need repair -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Lid(s) need repair:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <!-- Liquid operating level -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Liquid operating level:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;at outlet invert
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;above outlet invert
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;below outlet invert
          </td>
        </tr>

        
        <tr>
          <td style="padding:2px 0;">Scum layer thickness: (in.) </td>
          <td colspan="3" style="padding:2px 0;">Sludge layer thickness: (in.) </td>
        </tr>

        <!-- Tank pumping recommended -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Tank pumping recommended:(sludge plus scum occupy 25% or more of tank volume): </b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <!-- Tank pumped -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Tank pumped of all liquids and solids:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/A
          </td>
        </tr>


        <tr>
          <td style="padding:2px 0;"><b>Approx. volume pumped (gals): </b></td>
        </tr>

        <!-- Water stream flowing into tank from house -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Water stream flowing into tank from house:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;trickle
          </td>
          <td style="width:33.33%;">
            <span class="checkbox"></span>&nbsp;steady flow
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/A
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <!-- Water stream flowing into tank from house -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Water stream flowing into tank from drain field:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;trickle
          </td>
          <td style="width:33.33%;">
            <span class="checkbox"></span>&nbsp;steady flow
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/A
          </td>
          <td style="width:33.33%;"></td>
        </tr>


        <!-- Service recommended -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Service recommended:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/D
          </td>
        </tr>

        <!-- Accessible -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Inlet tee needs repair:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/D
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <!-- Accessible -->
        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Outlet tee needs repair:</b>
          </td>
        </tr>

        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/D
          </td>
          <td style="width:33.33%;"></td>
        </tr>

        <tr>
          <td style="padding:2px 0;">Tank composition </td>
          <td colspan="3" style="padding:2px 0;">Approx. size of tank (gals) </td>
        </tr>

        <tr>
          <td colspan="4" style="padding-top:6px; padding-bottom:2px;">
            <b>Service recommended:</b>
          </td>
        </tr>
        <tr>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;Yes
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;No
          </td>
          <td style="width:33.33%; padding:2px 0;">
            <span class="checkbox"></span>&nbsp;N/A
          </td>
        </tr>

        <tr>
          <td colspan="4" style="padding-top:10px; font-weight:bold; text-decoration:underline;">Comments:</td>
        </tr>
        <tr>
          <td colspan="4" style="padding:2px 0; height:40px; border-bottom:1px solid #aaa;"></td>
        </tr>

        <!-- Spacer -->
        <tr><td colspan="4" style="padding:10px 0;"></td></tr>

        <!-- Inspector Signature -->
        <tr>
          <td colspan="4" style="padding:4px 0;">
            Inspector Signature: 
          </td>
        </tr>

        <!-- Spacer -->
        <tr><td colspan="4" style="padding:6px 0;"></td></tr>

        <!-- Disclaimer -->
        <tr>
          <td colspan="4" style="padding:4px 0; font-style:italic; font-weight:bold;">
            Disclaimer: &nbsp;The above information indicates the conditions of the septic system at the time of inspection.
            This is not a guarantee or warranty of future system performance.
          </td>
        </tr>

        <!-- Spacer -->
        <tr><td colspan="4" style="padding:6px 0;"></td></tr>

        <!-- N/A and N/D legend -->
        <tr>
          <td style="padding:2px 0;"><b>N/A</b> = Not Applicable</td>
          <td colspan="3" style="padding:2px 0;"><b>N/D</b> = Not Determined</td>
        </tr>
      </table>
    </div>

